// check-docs.swift — hygiene for the hand-maintained markdown (rules/PRACTICES.md).
//   1. the `> **AGENTS: maintain this file with Haiku …**` banner near the top
//   2. every relative link resolves
//   3. no orphans: ATLAS.md or AGENTS.md links to every doc
// Scope: AGENTS.md and the .md files in .agents, harness, harness/rules, codebase, codebase/maps and reference. A file whose first lines say "Generated by" (a view `write render`
// writes) is skipped. Usage: check-docs   Exit 1 when anything is wrong; one `file: problem` line each.
import Foundation

let fm = FileManager.default
let proj = URL(fileURLWithPath: ProcessInfo.processInfo.environment["CLAUDE_PROJECT_DIR"] ?? fm.currentDirectoryPath)
    .resolvingSymlinksInPath()
let banner = "> **AGENTS: maintain this file with Haiku or a similar-class model, in grok'd prose.**"

/// Lists the markdown files directly inside a folder, sorted, as paths relative to the project root.
/// Takes the folder path relative to the project (empty for the root); returns the `.md` file paths, or an empty list if the folder is missing.
func docs(in dir: String) -> [String] {
    ((try? FileManager.default.contentsOfDirectory(atPath: proj.appendingPathComponent(dir).path)) ?? []).filter {
        $0.hasSuffix(".md")
    }
    .sorted().map { dir.isEmpty ? $0 : dir + "/" + $0 }
}
/// Lists `SKILL.md` files under `.agents/harness/skills/<name>`, sorted, relative to the project root.
func skillDocs() -> [String] {
    let base = ".agents/harness/skills"
    let names = ((try? FileManager.default.contentsOfDirectory(atPath: proj.appendingPathComponent(base).path)) ?? [])
        .filter { !$0.hasPrefix(".") }.sorted()
    return names.compactMap { name in
        let rel = "\(base)/\(name)/SKILL.md"
        return FileManager.default.fileExists(atPath: proj.appendingPathComponent(rel).path) ? rel : nil
    }
}
let scanned = [
    ".agents", ".agents/harness", ".agents/harness/rules",
    ".agents/codebase", ".agents/codebase/maps", ".agents/reference",
]
let files = ["AGENTS.md"] + scanned.flatMap { docs(in: $0) } + skillDocs()
var problems: [String] = []
var linked = Set<String>()  // docs that ATLAS.md or AGENTS.md link to
var checked: [String] = []

for rel in files {
    let url = proj.appendingPathComponent(rel)
    guard let text = try? String(contentsOf: url, encoding: .utf8) else { continue }
    let lines = text.components(separatedBy: "\n")
    if lines.prefix(3).contains(where: { $0.contains("Generated by") }) { continue }
    checked.append(rel)
    if !lines.prefix(8).contains(where: { $0.hasPrefix(banner) }) {
        problems.append("\(rel): missing the AGENTS banner in its first lines (see rules/PRACTICES.md)")
    }

    // links outside fenced code blocks
    var inFence = false
    var prose: [String] = []
    for l in lines {
        if l.hasPrefix("```") {
            inFence.toggle()
            continue
        }
        if !inFence { prose.append(l) }
    }
    let body = prose.joined(separator: "\n")
    guard let re = try? NSRegularExpression(pattern: #"\]\(([^)\s#]+)(?:#[^)]*)?\)"#) else { continue }
    for m in re.matches(in: body, range: NSRange(body.startIndex..., in: body)) {
        guard let r = Range(m.range(at: 1), in: body) else { continue }
        let target = String(body[r])
        if target.hasPrefix("http") || target.hasPrefix("mailto:") { continue }
        let resolved = url.deletingLastPathComponent().appendingPathComponent(target).standardizedFileURL
        if !fm.fileExists(atPath: resolved.path) {
            problems.append("\(rel): broken link \(target)")
            continue
        }
        if rel == "AGENTS.md" || rel == ".agents/ATLAS.md" {
            let prefix = proj.standardizedFileURL.path + "/"
            if resolved.path.hasPrefix(prefix) { linked.insert(String(resolved.path.dropFirst(prefix.count))) }
        }
    }
}
for rel in checked where rel != "AGENTS.md" && !linked.contains(rel) {
    problems.append("\(rel): nothing in ATLAS.md or AGENTS.md links to it (an orphan)")
}

problems.forEach { print($0) }
print(problems.isEmpty ? "ok: \(checked.count) doc(s)" : "\(problems.count) problem(s)")
exit(problems.isEmpty ? 0 : 1)
